"Android and apps then behave as if it was never set. It can be put back from the Undo bar or from Changes.": "Android dan aplikasi akan berperilaku seolah-olah nilai ini tidak pernah diatur. Bisa dikembalikan dari bilah Urungkan atau dari Perubahan.",
"Android asks whether this app may \"Run commands in Termux environment\".": "Android akan menanyakan apakah aplikasi ini boleh “Run commands in Termux environment”.",
"Android builds the palette from your home-screen wallpaper (what it does by default).": "Android membuat palet warna dari wallpaper layar utama (perilaku default).",
"Android builds the whole palette from the color below.": "Android membuat seluruh palet dari warna di bawah.",
"Android can't verify this APK's signature (edited after signing, or unsigned).": "Android tidak dapat memverifikasi tanda tangan APK ini (diedit setelah ditandatangani, atau belum ditandatangani).",
"Android can't verify this APK's signature (edited after signing, or unsigned). It is tried as it is first; if Android refuses it, a copy signed with this app's key is installed.": "Android tidak dapat memverifikasi tanda tangan APK ini (diedit setelah ditandatangani, atau belum ditandatangani). APK dicoba apa adanya lebih dulu; jika Android menolaknya, salinan yang ditandatangani dengan kunci aplikasi ini akan diinstal.",
"Android is clearing the caches. This can take up to a minute or two; you can keep using the app.": "Android sedang menghapus cache. Ini bisa memakan waktu hingga satu atau dua menit; Anda tetap bisa memakai aplikasi.",
"Android keeps its settings behind the shell. Connect one of them in Working Modes, then come back.": "Android menyimpan pengaturannya di balik shell. Hubungkan salah satunya di Mode Kerja, lalu kembali.",
"Android lists this overlay as unavailable": "Android menandai overlay ini sebagai tidak tersedia",
"Android lists this overlay as unavailable (its target app is missing, or it is not approved), so it cannot be switched.": "Android menandai overlay ini sebagai tidak tersedia (aplikasi targetnya tidak ada, atau belum disetujui), sehingga tidak bisa diaktifkan atau dinonaktifkan.",
"Android only uses a setting that something reads by that name. Leave the value empty to create it with nothing in it.": "Android hanya memakai pengaturan jika ada yang membacanya dengan nama tersebut. Kosongkan nilai untuk membuatnya tanpa isi.",
"Android repaints in a moment, and apps may restart.": "Android akan memuat ulang tampilan sebentar lagi, dan aplikasi mungkin dimulai ulang.",
"Android reports no signing certificate for this app.": "Android tidak melaporkan sertifikat penandatanganan untuk aplikasi ini.",
"Android version": "Versi Android",
"Android versions": "Versi Android",
"Android will not ask again. Allow it by hand: App info of this app, Permissions, Additional permissions, Run commands in Termux environment.": "Android tidak akan bertanya lagi. Izinkan secara manual: Info aplikasi untuk aplikasi ini, Izin, Izin tambahan, “Run commands in Termux environment”.",
"Android will use your wallpaper’s colors with the Tonal Spot style again.": "Android akan kembali memakai warna dari wallpaper Anda dengan gaya Tonal Spot.",
"Android’s hidden settings": "Pengaturan tersembunyi Android",
