"Anthropic does not allow other apps to sign in with a Claude Pro or Max account. Claude Code, Anthropic's own tool, can: it runs in Termux, and the Terminal chats through it. With an API key saved, Claude Code uses the key instead.": "Anthropic tidak mengizinkan aplikasi lain login dengan akun Claude Pro atau Max. Claude Code, alat milik Anthropic sendiri, bisa: alat ini berjalan di Termux, dan chat di Terminal disalurkan lewat alat itu. Jika kunci API sudah disimpan, Claude Code memakai kunci itu sebagai gantinya.",
"Any screen density": "Kepadatan layar apa pun",
"Anyone who has the password can open it. If it is lost, the files can not be recovered.": "Siapa pun yang memiliki kata sandi dapat membukanya. Jika kata sandi hilang, file tidak dapat dipulihkan.",
"AnythingLLM": "AnythingLLM",
"AnythingLLM runs on a computer or a server (Desktop or Docker). Enter its address (like http://192.168.1.20:3001/api/v1/openai) and an API key from AnythingLLM, Settings, Developer API. Each workspace shows up as a model.": "AnythingLLM berjalan di komputer atau server (Desktop atau Docker). Masukkan alamatnya (misalnya http://192.168.1.20:3001/api/v1/openai) dan kunci API dari AnythingLLM, Settings, Developer API. Setiap workspace muncul sebagai model.",
