"Choose the sign-in method in the agent's Connect sheet. The tools are installed into a Debian environment inside Termux when they have no Android build. This takes several minutes and up to about 1 GB; the providers do not support Android officially, so a tool may not run on every phone.": "Pilih metode login di lembar koneksi agen. Jika alatnya tidak punya versi Android, alat itu diinstal ke lingkungan Debian di dalam Termux. Proses ini memakan waktu beberapa menit dan hingga sekitar 1 GB; penyedia tidak mendukung Android secara resmi, jadi alat mungkin tidak berjalan di semua ponsel.",
"Choose what the extra button on each row of the Apps list does. It is always an icon, and the ones that change with the app (Enable / Disable, Install / Uninstall, Unsuspend / Suspend) switch their icon and action to match the app's current state.": "Pilih fungsi tombol tambahan di setiap baris daftar Aplikasi. Tombol ini selalu berupa ikon, dan yang berubah sesuai aplikasi (Aktifkan / Nonaktifkan, Instal / Uninstal, Lepas penangguhan / Tangguhkan) mengganti ikon dan tindakannya agar sesuai dengan status aplikasi saat ini.",
"Choosing files works in the app": "Pemilihan file berfungsi di aplikasi",
"Claude": "Claude",
"Claude (Anthropic)": "Claude (Anthropic)",
"Claude Code": "Claude Code",
"Claude Pro or Max and a Google account login may only be used in the providers' own apps: Anthropic and Google do not allow other apps to use those logins. So the Terminal signs you in through the official command-line tools running in Termux, where the provider's own website login opens:": "Claude Pro atau Max dan login akun Google hanya boleh dipakai di aplikasi milik penyedianya sendiri: Anthropic dan Google tidak mengizinkan aplikasi lain memakai login tersebut. Jadi, Terminal memproses login Anda lewat alat baris perintah resmi yang berjalan di Termux, tempat halaman login di situs web penyedia itu sendiri dibuka:",
