"It could not be saved": "Tidak dapat disimpan",
"It did not finish": "Tidak selesai",
"It did not work": "Tidak berhasil",
"It finishes installing itself the first time it opens.": "Termux menyelesaikan instalasinya sendiri saat pertama kali dibuka.",
"It goes back to the version that came with the phone. An older version often cannot use the data of a newer one, so it may lose its data.": "Aplikasi akan kembali ke versi bawaan ponsel. Versi lama sering kali tidak dapat memakai data versi yang lebih baru, sehingga datanya bisa hilang.",
"It has no Android build, so it goes into a Debian container inside Termux (several minutes, a few hundred MB). Already installed steps are skipped quickly.": "Alat ini tidak punya versi Android, jadi diinstal ke kontainer Debian di dalam Termux (beberapa menit, beberapa ratus MB). Langkah yang sudah selesai dilewati dengan cepat.",
"It is not set any more": "Tidak lagi diatur",
"It is removed for the device's user. A system app can be put back with Reinstall.": "Aplikasi dihapus untuk pengguna perangkat. Aplikasi sistem dapat dikembalikan dengan Instal ulang.",
"It is removed for you. A system app stays on the phone and can be brought back with Reinstall.": "Aplikasi dihapus untuk Anda. Aplikasi sistem tetap ada di ponsel dan dapat dikembalikan dengan Instal ulang.",
"It is tried as it is first; if Android refuses it, a copy signed with this app's key is installed.": "APK dicoba apa adanya lebih dulu; jika Android menolaknya, salinan yang ditandatangani dengan kunci aplikasi ini akan diinstal.",
"Its settings, accounts and files on the device are deleted.": "Pengaturan, akun, dan file-nya di perangkat akan dihapus.",
"Its settings, accounts, saved games and the files in its own storage are deleted. This cannot be undone.": "Pengaturan, akun, game tersimpan, dan file di penyimpanannya sendiri akan dihapus. Tindakan ini tidak dapat diurungkan.",
"IzzyOnDroid": "IzzyOnDroid",
"IzzyOnDroid page": "Halaman IzzyOnDroid",
"Jan runs AI models on your computer, free. On the computer: Jan, Settings, Local API Server: set the host to 0.0.0.0 and start it, then enter the computer's address here (like http://192.168.1.20:1337/v1). There is no Android version of Jan.": "Jan menjalankan model AI di komputer Anda, gratis. Di komputer: Jan, Settings, Local API Server: atur host ke 0.0.0.0 lalu jalankan servernya, kemudian masukkan alamat komputer di sini (misalnya http://192.168.1.20:1337/v1). Jan tidak punya versi Android.",
