"Keys are encrypted with a key that stays in the phone's secure hardware, and they are only ever sent to their own provider's address. The page never sees them again after you type them; only the last four characters are shown.": "Kunci dienkripsi dengan kunci yang tetap berada di perangkat keras aman ponsel, dan hanya dikirim ke alamat penyedianya masing-masing. Halaman ini tidak pernah melihatnya lagi setelah Anda mengetiknya; hanya empat karakter terakhir yang ditampilkan.",
