"Left the Rish shell: the working mode changed.": "Keluar dari shell Rish: mode kerja berubah.",
"Lenovo": "Lenovo",
"Leon is an open-source personal assistant (skills, voice) that runs on a computer with Node.js and Python. It has no Android version and is not a coding agent, so it does not chat in this Terminal.": "Leon adalah asisten pribadi sumber terbuka (skill, suara) yang berjalan di komputer dengan Node.js dan Python. Leon tidak punya versi Android dan bukan agen koding, jadi tidak bisa chat di Terminal ini.",
"Leon.ai": "Leon.ai",
"Let Termux take commands from other apps": "Izinkan Termux menerima perintah dari aplikasi lain",
"Let them act without asking": "Biarkan bertindak tanpa bertanya",
"Lets the agent read and write files under the folder named at the end of the command (change /sdcard to taste).": "Memungkinkan agen membaca dan menulis file di dalam folder yang disebut di akhir perintah (ubah /sdcard sesuai kebutuhan).",
"Lets the agent think in explicit steps before it acts.": "Memungkinkan agen berpikir dalam langkah-langkah eksplisit sebelum bertindak.",
"Lets this app change a few protected system settings used by some advanced features.": "Memungkinkan aplikasi ini mengubah beberapa pengaturan sistem yang dilindungi, yang dipakai oleh sejumlah fitur lanjutan.",
"Lets this app install the package files you choose, such as APK, APKS and XAPK files from your storage.": "Memungkinkan aplikasi ini menginstal file paket yang Anda pilih, seperti file APK, APKS, dan XAPK dari penyimpanan Anda.",
