"The device's system, secure and global settings. A wrong value can make a device misbehave: change one at a time.": "Pengaturan System, Secure, dan Global perangkat. Nilai yang salah dapat membuat perangkat bermasalah: ubah satu per satu.",
"The edit could not start": "Pengeditan tidak dapat dimulai",
"The extra keys work like Termux's: ESC clears the line, TAB completes a file name, CTRL-C stops what is running, the arrows go through earlier commands and move the cursor, HOME and END jump in the line, and | / - ~ are there because phone keyboards hide them.": "Tombol tambahan bekerja seperti di Termux: ESC menghapus baris, TAB melengkapi nama file, CTRL-C menghentikan proses yang berjalan, tanda panah menelusuri perintah sebelumnya dan menggerakkan kursor, HOME dan END melompat di dalam baris, dan | / - ~ disediakan karena keyboard ponsel menyembunyikannya.",
"The extraction could not start": "Ekstraksi tidak dapat dimulai",
"The file": "File",
"The file chooser needs the app build": "Pemilih file memerlukan versi resmi aplikasi",
