"This app cannot read storage. Grant All-files access, or choose a font file by hand (that needs no access).": "Aplikasi ini tidak dapat membaca penyimpanan. Berikan akses ke semua file, atau pilih file font secara manual (tidak perlu akses).",
"This app does not ask for a particular touch screen, keyboard or navigation (it has no uses-configuration entry), so it runs with whatever this phone has.": "Aplikasi ini tidak meminta layar sentuh, keyboard, atau navigasi tertentu (tanpa entri uses-configuration), sehingga berjalan dengan apa pun yang dimiliki ponsel ini.",
"This app does not list any hardware or software features it needs (no uses-feature entries).": "Aplikasi ini tidak mencantumkan fitur perangkat keras atau perangkat lunak yang dibutuhkan (tanpa entri uses-feature).",
"This app has no activities.": "Aplikasi ini tidak memiliki activity.",
"This app may not run commands in Termux yet.": "Aplikasi ini mungkin belum dapat menjalankan perintah di Termux.",
"This app now has its own private ADB key. Tap the mode badge for details.": "Aplikasi ini kini memiliki kunci ADB pribadi sendiri. Ketuk lencana mode untuk detailnya.",
"This app's own shell - no root, ADB or package manager.": "Shell milik aplikasi ini - tanpa root, ADB, atau manajer paket.",
"This app's own user and group id": "ID pengguna dan grup milik aplikasi ini",
